-- Move each identity sequence above the ids inserted above,
-- so new rows (for example in exercise 15) get new ids.
ALTER TABLE departments MODIFY (department_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE employees MODIFY (employee_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE equipment MODIFY (equipment_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
ALTER TABLE maintenance_requests MODIFY (request_id GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE));
